    ".......#########......",
    ".......########.......",
    ".......####...........",
    "#......####...........",
    "#.....########........",
    "###..######..#........",
    ".##########...........",
    ".##########...........",
    "..#########...........",
    "...#######............",
    "....#####.............",
];

const legs = [
  [
    "....##.##.....",
    "....#..#......",
