"..............#######.",
".............###.#####",
".............#########",
"###.........#########.",
"..###....#######......",
"...#############......",
"...###############....",
"....###########..#....",
".....########.........",
"......######..........",
];

const duckLegs = [
  [
    "....##.##.....",
    "....#..#......",
    "....#..##.....",
    "....##........",
  ],
  [
    "....##.##.....",
    "....#..#......",
    "....##.#......",
    ".......##.....",
  ],
];
  const ptero = [
    [
      ".............##..........",
      "...........#####.........",
      "..........######........",
      ".....#...########.......",
      "...###...##########....#..",
      "..####...############.##..",
