      "...###....................",
      "..####..................#.",
      ".##.####...............##.",
      "#########.###############.",
      "..#####.################.",
      "........###############...",
      "........#############.....",
      "........###########.......",
      "........#########.........",
      ".........#######..........",
      "..........####............",
      "...........##.............",
    ],
  ];
  const CACTUS_HEIGHTS = [[42, 64], [36, 58], [32, 50]];
  const DINO_W = 16 * PX;
  const DINO_H = (body.length + 4) * PX;
