  }

  function hit() {
    const d = dinoBox();
    return obstacles.some((o) =>
      obstacleBoxes(o).some((b) => d.x < b.x + b.w && d.x + d.w > b.x && d.y < b.y + b.h && d.y + d.h > b.y),
    );
  }

  function update(k) {
    speed = Math.min(22, 6 + score / 250);
    score += speed * 0.1 * k;
    dino.vy += (GRAVITY + (!dino.onGround && duckHeld ? FAST_FALL : 0)) * k;
