    obstacles = obstacles.filter((o) => o.x + o.w > -10);
    ground.forEach((g) => {
      g.x -= speed * k;
      if (g.x + g.w < 0) {
        g.x += W + 40;
        g.w = 6 + Math.random() * 18;
      }
    });
    if (hit()) {
      running = false;
      best = Math.max(best, Math.floor(score));
    }
  }

  function drawDino() {
    ctx.fillStyle = running ? colors.accent : "#ff4444";
