    : { start: "PULSA ESPACIO O TOCA PARA EMPEZAR", over: "GAME OVER - ESPACIO / ENTER / TOCA", hi: "HI" };

  const body = [
    ".........#####........",
    "........#######.......",
    ".......###.#####......",
    ".......#########......",
    ".......########.......",
    ".......####...........",
    "#......####...........",
    "#.....########........",
    "###..######..#........",
    ".##########...........",
    ".##########...........",
    "..#########...........",
    "...#######............",
    "....#####.............",
];

const legs = [
  [
    "....##.##.....",
    "....#..#......",
    "....#..##.....",
    "....##........",
  ],
  [
    "....##.##.....",
    "....#..#.....",
    "....##.#......",
    ".......##.....",
  ],
];

