"......................",
"......................",
"......................",
"...............#####..",
"..............#######.",
".............###.#####",
".............#########",
"###.........#########.",
"..###....#######......",
"...#############......",
"...###############....",
"....###########..#....",
".....########.........",
"......######..........",
];

