  [
    "....##.##.....",
    "....#..#......",
    "....#..##.....",
    "....##........",
  ],
  [
    "....##.##.....",
    "....#..#......",
    "....##.#......",
    ".......##.....",
  ],
];
  const ptero = [
    [
      ".............##..........",
      "...........#####.........",
      "..........######........",
      ".....#...########.......",
      "...###...##########....#..",
      "..####...############.##..",
      ".##.####.###############..",
      "#########.##############..",
      "..#####....############...",
      "...........#######........",
      "..........................",
      "..........................",
      "..........................",
      "..........................",
      "..........................",
      "..........................",
    ],
    [
      "..........................",
      "..........................",
      "..........................",
      ".....#....................",
      "...###....................",
      "..####..................#.",
      ".##.####...............##.",
      "#########.###############.",
      "..#####.################.",
      "........###############...",
      "........#############.....",
      "........###########.......",
      "........#########.........",
      ".........#######..........",
      "..........####............",
      "...........##.............",
    ],
  ];
