    speed = 6;
    score = 0;
    running = true;
    legFrame = 0;
    legTick = 0;
    wingTick = 0;
    spawnIn = 60;
  }

  function isDucking() {
    return duckHeld && dino.onGround && running;
  }

  function jump() {
    if (!started) started = true;
    if (!running) return reset();
    if (dino.onGround && !duckHeld) {
      dino.vy = JUMP;
