    ctx.fillStyle = running ? colors.accent : "#ff4444";
    if (isDucking()) {
      const y = GROUND - DUCK_H;
      drawSprite(duckBody, dino.x, y);
      drawSprite(duckLegs[legFrame], dino.x + 3 * PX, y + duckBody.length * PX);
